const test = require('node:test');
const assert = require('node:assert/strict');
const { totalCents } = require('./cart.cjs');
test('empty cart', () => assert.equal(totalCents([]), 0));
test('quantities multiply unit price', () => assert.equal(totalCents([{unitCents: 125, quantity: 3}, {unitCents: 50, quantity: 2}]), 475));
test('input array and records remain unchanged', () => {
  const lines = [{ unitCents: 125, quantity: 3 }, { unitCents: 50, quantity: 2 }];
  const originalRecords = [...lines];
  const originalValues = lines.map(line => ({ ...line }));

  assert.equal(totalCents(lines), 475);
  assert.deepEqual(lines, originalValues);
  lines.forEach((line, index) => assert.strictEqual(line, originalRecords[index]));
});
